import{_ as a,a as e,b as i}from"./chunks/portal-selection.Bw9NU4ob.js";import{_ as t,o as n,c as o,a2 as l}from"./chunks/framework.CN568Poi.js";const u=JSON.parse('{"title":"Download","description":"","frontmatter":{},"headers":[],"relativePath":"download.md","filePath":"download.md","lastUpdated":1795430985000}'),d={name:"download.md"};function r(p,s,h,c,k,g){return n(),o("div",null,[...s[0]||(s[0]=[l('<h1 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h1><p>Two supported routes: the portal with the command it generates, or the same <code>humancoin-download</code> command typed by hand.</p><h2 id="the-data-portal" tabindex="-1">The data portal <a class="header-anchor" href="#the-data-portal" aria-label="Permalink to &quot;The data portal&quot;">​</a></h2><p>The <strong><a href="https://flagopen.github.io/HumanCOIN-DataManager/" target="_blank" rel="noreferrer">HumanCOIN DataManager</a></strong> is the public catalog for released data.</p><p align="center"><img src="'+a+'" alt="Explore Datasets: search, filters and dataset cards" width="85%"><br><sub>Explore Datasets: search and compare released repositories; each card exposes its sensor set, size and Preview/Download actions.</sub></p><p align="center"><img src="'+e+`" alt="Dataset card with task, sensors, size and Get Download Command" width="65%"><br><sub>A dataset card: task, per-stream metadata, episode count, duration, size, license, and Get Download Command.</sub></p><ol><li><strong>Browse.</strong> Filter by data level, modality, scene, task and main-camera resolution.</li><li><strong>Preview.</strong> Check the task, stream list, episodes, duration, size and license.</li><li><strong>Select.</strong> Tick one or more complete repositories. The selection is kept in browser storage and can be exported/imported as <code>selection.json</code>.</li><li><strong>Choose a source.</strong> Hugging Face or ModelScope. A repository may exist on one hub only.</li><li><strong>Generate the command.</strong> The command selects the revision shown on the card.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">humancoin-download</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> huggingface</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --datasets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;HumanCOIN/&lt;repository&gt;&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --revision</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&lt;commit-or-master&gt;&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --target-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-workers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span></span></code></pre></div><p>Run it in the terminal where you authenticated. <code>--dry-run</code> prints the destination and include/exclude patterns without downloading.</p><h2 id="repository-names" tabindex="-1">Repository names <a class="header-anchor" href="#repository-names" aria-label="Permalink to &quot;Repository names&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>l1_study_room_fill_task_1920x1456_30fps_2views</span></span>
<span class="line"><span>│  │          │    │        │      │     └─ released camera views</span></span>
<span class="line"><span>│  │          │    │        │      └─ frame rate</span></span>
<span class="line"><span>│  │          │    │        └─ main camera resolution</span></span>
<span class="line"><span>│  │          │    └─ task</span></span>
<span class="line"><span>│  │          └─ scene</span></span>
<span class="line"><span>│  └─ tier</span></span></code></pre></div><p>L2/L3 names add the sensor kit, e.g. <code>..._9views_emg8</code> or <code>..._12views_eeg128_emg8</code>.</p><h2 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">humancoin-download</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or: python -m humancoin.download --help</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--hub {huggingface,modelscope}</code></td><td>source hub</td></tr><tr><td><code>--datasets A B ...</code></td><td>one or more repository names or <code>owner/name</code> IDs</td></tr><tr><td><code>--revision REV</code></td><td>branch, tag or commit</td></tr><tr><td><code>--target-dir DIR</code></td><td>download root; files go to <code>DIR/HumanCOIN/&lt;name&gt;</code></td></tr><tr><td><code>--max-workers N</code></td><td>parallel downloads</td></tr><tr><td><code>--include</code> / <code>--exclude</code></td><td>relative-path globs for partial downloads</td></tr><tr><td><code>--dry-run</code></td><td>print the plan only</td></tr><tr><td><code>--token TOKEN</code></td><td>access token; prefer environment variables</td></tr></tbody></table><p>Examples:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># several repositories</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">humancoin-download</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> huggingface</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --datasets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;HumanCOIN/l1_study_room_fill_task_1920x1456_30fps_2views&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">             &#39;HumanCOIN/l3_bedroom_fold_clothes_eye_1600x1200_30fps_12views_eeg128_emg8&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --target-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-workers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># inspect the plan</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">humancoin-download</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --datasets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;HumanCOIN/l1_study_room_fill_task_1920x1456_30fps_2views&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --target-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span></code></pre></div><p>Re-running resumes: the hub SDK reuses files already present. A failure on one repository does not stop the others; the process exits nonzero if any fail.</p><h2 id="hugging-face-access" tabindex="-1">Hugging Face access <a class="header-anchor" href="#hugging-face-access" aria-label="Permalink to &quot;Hugging Face access&quot;">​</a></h2><p>Most repositories are gated. Open the dataset page, request access, wait for approval, then:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> whoami</span></span></code></pre></div><p>A 401/403 usually means the approval is missing or the token belongs to a different account.</p><h2 id="modelscope" tabindex="-1">ModelScope <a class="header-anchor" href="#modelscope" aria-label="Permalink to &quot;ModelScope&quot;">​</a></h2><p>ModelScope mirrors the catalog. For a gated repository:</p><ol><li>Request access on the ModelScope dataset page with the account you will use.</li><li>Create a <a href="https://modelscope.cn/my/myaccesstoken" target="_blank" rel="noreferrer">ModelScope access token</a> from that same account.</li><li>Export it interactively so it does not land in shell history:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">read</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rsp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;ModelScope Token: &#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MODELSCOPE_TOKEN</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;\\n&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MODELSCOPE_TOKEN</span></span></code></pre></div><ol start="4"><li>Select the repository, switch the source to <strong>ModelScope</strong>, and generate the command:</li></ol><p align="center"><img src="`+i+`" alt="ModelScope selection and Generate Download Command" width="100%"><br><sub>Select complete repositories, choose ModelScope, then Generate Download Command. The same bar exports selection.json.</sub></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">humancoin-download</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modelscope</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --datasets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;HumanCOIN/l2_workroom_write_workpiece_markings_left_1920x1200_30fps_9views_emg8&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --revision</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;master&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --target-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-workers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span></span></code></pre></div><p>Files land in <code>./data/HumanCOIN/&lt;repository&gt;/</code>, with the same layout as Hugging Face. <code>--dry-run</code>, <code>--include</code>/<code>--exclude</code> and <code>selection.json</code> work the same for both hubs. The downloader reads <code>MODELSCOPE_TOKEN</code> or <code>MS_TOKEN</code>; <code>--token</code> also works. <code>master</code> is mutable: pin a commit or tag when you need byte-identical reproducibility.</p><h2 id="disk-and-verification" tabindex="-1">Disk and verification <a class="header-anchor" href="#disk-and-verification" aria-label="Permalink to &quot;Disk and verification&quot;">​</a></h2><p>Sizes vary: the quick-start L1 example is 65 MB, while L2/L3 repositories are multi-GB and the largest exceed 60 GB. The full published catalog is roughly 7.5 TB.</p><p>A flat L2/L3 repository has <code>meta/info.json</code> at its root; an L1 repository has one <code>&lt;task&gt;/meta/info.json</code> per recording. A complete task directory also has at least one <code>data/chunk-*/episode_*/master_index.parquet</code>.</p>`,33)])])}const C=t(d,[["render",r]]);export{u as __pageData,C as default};
